import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
session_name = os.path.basename(d)
t = open(d+'/../../sessions/'+session_name+'.jsonl').read().replace('\\n', '\n')

G = {}

# Parse each demo pair and test input
for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    kind = match.group(1)  # e.g., "Demo pair 1 input" or "Test input"
    height = int(match.group(2))
    width = int(match.group(3))

    # Get the next 'height' lines after the header
    rows = []
    pos = match.end()
    while len(rows) < height and pos < len(t):
        pos = t.find('\n', pos)
        if pos == -1:
            break
        lines = t[pos+1:pos+height+1].split('\n')
        # Filter for valid grid lines
        for line in lines:
            if line.strip() and not line.startswith('{'):
                row_vals = []
                for token in line.split():
                    if token.isdigit():
                        try:
                            row_vals.append(int(token))
                        except:
                            pass
                # Check if this is a valid row
                if len(row_vals) == width and all(0 <= x <= 9 for x in row_vals):
                    if rows:
                        rows[-1] = row_vals
                    else:
                        rows.append(row_vals)
                # Stop when we see a blank line or JSON object
                if not line.strip() or line.startswith('{'):
                    break

    # Use kind as the key
    full_key = kind
    if full_key not in G:
        G[full_key] = rows

print("Keys found:", list(G.keys()))
print("\nTest input:")
print(G.get("Test input", "Not found"))

import os, re, json

# Load grids
d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()

G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Grids loaded:", list(G.keys()))
for k, v in G.items():
    print(f"  {k}: {v[0]}")
